const $=id=>document.getElementById(id);let config,manifest,pending,worker,ready=false,current='',page=1,requestId=0,history=[],save=true;
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
const safeUrl=(s,base=location.href)=>{const u=new URL(s,base);if(!['https:','http:'].includes(u.protocol))throw Error('Invalid URL');return u.href};
async function getJson(url){const r=await fetch(url,{cache:'no-cache',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('取得失敗');return r.json()}
try{save=localStorage.getItem('fvtd-save')!=='false';const h=JSON.parse(localStorage.getItem('fvtd-history')||'[]');history=save&&Array.isArray(h)?h.filter(x=>typeof x==='string').slice(0,20):[]}catch{$('storage-note').textContent='このブラウザでは履歴を保存できません。'}
$('save-history').checked=save;
function persist(){try{localStorage.setItem('fvtd-save',String(save));localStorage.setItem('fvtd-history',JSON.stringify(history))}catch{$('storage-note').textContent='履歴はこの画面を閉じるまでのみ保持されます。'}}
function renderHistory(){$('history').replaceChildren();if(!history.length){$('history').append(el('span',save?'検索すると、ここに履歴が表示されます。':'履歴の保存はオフです。','hint'));return}for(const q of history){const chip=el('span',undefined,'chip');const b=el('button',q);b.onclick=()=>{$('query').value=q;search(q)};const rm=el('button','×','remove');rm.setAttribute('aria-label',q+'を履歴から削除');rm.onclick=()=>{history=history.filter(x=>x!==q);persist();renderHistory()};chip.append(b,rm);$('history').append(chip)}}
$('save-history').onchange=e=>{save=e.target.checked;if(!save)history=[];persist();renderHistory()};$('clear-history').onclick=()=>{history=[];persist();renderHistory()};renderHistory();
function card(r){const n=el('article',undefined,'result-card');n.append(el('strong',r.word),el('div',r.reading,'reading'));for(const x of r.excluded||[])n.append(el('div',x.ime+'向け辞書には含まれません：'+x.reason,'warning'));return n}
function requestBox(q){const p=config.formPrefill,u=new URL(safeUrl(config.formUrl));u.searchParams.set('usp','pp_url');u.searchParams.set('entry.'+p.type,p.newType);u.searchParams.set('entry.'+(/^[ぁ-ゖー]+$/.test(q)?p.reading:p.name),q);const box=el('div',undefined,'request-box'),a=el('a','「'+q+'」の収録を依頼する ↗');a.href=u.href;a.target='_blank';a.rel='noopener';box.append(el('p','「'+q+'」に完全一致する登録語はありません。未収録のVTuberであれば、フォームから収録を依頼できます（入力した語がフォームに記入された状態で開きます）。'),a);return box}
function search(q,p=1,remember=true){if(!q.length||!ready)return;current=q;page=p;if(remember&&save){history=[q,...history.filter(x=>x!==q)].slice(0,20);persist();renderHistory()}$('status').textContent='検索しています…';worker.postMessage({type:'search',q,page:p,id:++requestId})}
$('search-form').onsubmit=e=>{e.preventDefault();search($('query').value)};
function showResults(r){if(r.id!==requestId)return;$('exact').replaceChildren();$('candidates').replaceChildren();$('pagination').replaceChildren();$('status').textContent=r.exact.length?'完全一致する登録語があります。':'完全一致する登録語はありません。';if(!r.exact.length&&config.formUrl&&config.formPrefill)$('exact').append(requestBox(r.q));if(r.exact.length){const box=el('div',undefined,'exact-box');box.append(el('h3','✓ 完全一致 · '+r.exact.length+'件'));for(const row of r.exact)box.append(card(row));$('exact').append(box)}$('result-count').textContent='部分一致 '+r.total.toLocaleString()+'件';for(const row of r.items)$('candidates').append(card(row));if(!r.items.length&&!r.exact.length)$('candidates').append(el('p','別の名前や読み、短い文字列で検索してみてください。','hint'));if(r.total>20){const prev=el('button','前へ'),next=el('button','次へ');prev.disabled=page===1;next.disabled=page>=Math.ceil(r.total/20);prev.onclick=()=>search(current,page-1,false);next.onclick=()=>search(current,page+1,false);$('pagination').append(prev,el('span',page+' / '+Math.ceil(r.total/20)),next)}}
function renderManifest(m){$('entry-count').textContent=m.count.toLocaleString()+'語';$('download').href=safeUrl(m.zip,config.manifestUrl);$('download').download='F-VTD-'+m.version+'.zip';$('download').removeAttribute('aria-disabled');$('download').textContent=config.demo?'↓ 確認用ZIPをダウンロード':'↓ すべての辞書をダウンロード';$('download-top').href=$('download').href;$('download-top').download=$('download').download;$('version').textContent=m.version+' · '+m.count.toLocaleString()+'語 · '+new Date(m.updatedAt).toLocaleDateString('ja-JP');$('changelog').replaceChildren();for(const c of (m.changes||[]).slice(0,5)){const box=el('article',undefined,'change'),body=el('div');box.append(el('time',new Date(c.date).toLocaleDateString('ja-JP')));body.append(el('strong',c.title||'辞書を更新'),el('p','追加 '+c.added.length+'件 / 削除 '+c.removed.length+'件'));const d=el('details');d.append(el('summary','変更された語を見る'));for(const [label,rows]of [['追加',c.added],['削除',c.removed]])for(const r of rows)d.append(el('p',label+'：'+r.word+'（'+r.reading+'）'));body.append(d);box.append(body);$('changelog').append(box)}}
async function load(m){if(!m||typeof m.version!=='string'||typeof m.data!=='string'||typeof m.zip!=='string'||!Number.isInteger(m.count)||!Array.isArray(m.changes)||!Number.isFinite(Date.parse(m.updatedAt)))throw Error('Manifest invalid');safeUrl(m.zip,config.manifestUrl);const rows=await getJson(safeUrl(m.data,config.manifestUrl));if(!Array.isArray(rows)||rows.length!==m.count||rows.some(r=>typeof r.word!=='string'||typeof r.reading!=='string'||(r.excluded&&!Array.isArray(r.excluded))))throw Error('データ形式不正');rows.sort((a,b)=>a.reading.localeCompare(b.reading,'ja')||a.word.localeCompare(b.word,'ja'));const next=new Worker('/search-worker.js');await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{next.terminate();reject(Error('検索準備タイムアウト'))},20000);next.onerror=()=>{clearTimeout(timeout);next.terminate();reject(Error('検索準備失敗'))};next.onmessage=e=>{if(e.data.type==='ready'){clearTimeout(timeout);resolve()}};next.postMessage({type:'load',rows})});worker?.terminate();worker=next;worker.onmessage=e=>showResults(e.data);manifest=m;renderManifest(m);ready=true;$('search-button').disabled=false;$('retry').hidden=true;$('status').textContent='名前や読みを入力して、収録状況を確認できます。';if(current)search(current,1,false)}
async function check(){if(document.hidden||!manifest)return;try{const m=await getJson(config.manifestUrl);if(m.version!==manifest.version){pending=m;$('update-banner').hidden=false}}catch{/* Keep last validated snapshot. */}}
$('apply-update').onclick=async()=>{if(!pending)return;$('apply-update').disabled=true;try{await load(pending);pending=null;$('update-banner').hidden=true}catch{$('status').textContent='更新を取得できませんでした。現在の版を引き続き利用できます。'}finally{$('apply-update').disabled=false}};
async function init(){$('search-button').disabled=true;try{config=await getJson('/config.json');config.manifestUrl=safeUrl(config.manifestUrl);if(!config.demo){document.querySelector('.demo').hidden=true;document.querySelector('.download-note').textContent='ZIP内の案内・利用条件をご確認ください。'}for(const[id,url,text]of [['repo-link',config.githubUrl,'GitHub ↗'],['past-link',config.githubUrl?config.githubUrl+'/commits/main/data/master.tsv':'','過去の変更をGitHubで見る ↗']])if(url){const a=el('a',text);a.href=safeUrl(url);a.rel='noopener';$(id).replaceChildren(a)}if(config.issuesUrl||config.formUrl){$('contact-links').replaceChildren();for(const[url,text]of [[config.issuesUrl,'GitHub Issues ↗'],[config.formUrl,'Googleフォーム ↗']])if(url){const a=el('a',text);a.href=safeUrl(url);$('contact-links').append(a)}}await load(await getJson(config.manifestUrl))}catch{$('status').textContent='辞書を読み込めませんでした。未収録の判定は行っていません。再読み込みをお試しください。';$('retry').hidden=false}}
$('retry').onclick=init;setInterval(check,300000);document.addEventListener('visibilitychange',check);
for(const[name,url]of [['Microsoft IME','https://support.microsoft.com/ja-jp/windows/hardware/input-devices/microsoft-japanese-ime'],['Google日本語入力','https://www.google.co.jp/ime/'],['Mozc','https://github.com/google/mozc'],['ATOK','https://atok.com/useful/'],['macOS追加辞書','https://support.apple.com/ja-jp/guide/japanese-input-method/jpim10226/mac']]){const a=el('a',name+' ↗');a.href=url;a.target='_blank';a.rel='noopener';$('help-links').append(a)}
init();
